{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"CA","category":"application_screening_fees","lifecycle":"enacted","title":"California tenant screening fee cap (Civ. Code § 1950.6)","requirement":"A landlord may not charge a screening fee above the annual cap, must give the applicant a receipt, an itemized list of out-of-pocket costs and time, a refund of any unused portion and a copy of the credit report within 7 days, and may not charge a fee when no unit is available.","key_value":"$68.96 maximum screening fee for 2026","coverage_conditions":"Landlords and their agents who charge an applicant a screening fee for a residential rental unit.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Residential rental applicants statewide"},"exemptions":null,"penalty":null,"effective_date":"2026","citation":"Cal. Civ. Code § 1950.6","quoted_span":"The maximum tenant screening fee for 2026 is $68.96","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"CA","category":"screening_restrictions","lifecycle":"enacted","title":"California reusable screening report requirement (Civ. Code § 1950.6)","requirement":"If a prospective tenant provides a reusable screening report, the landlord must use it rather than requiring a new screening; the applicant is also entitled to a copy of the credit report obtained within 7 days.","key_value":null,"coverage_conditions":"Landlords screening applicants for residential rental units who receive a reusable screening report from the applicant.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Residential rental applicants statewide"},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Cal. Civ. Code § 1950.6","quoted_span":"If the tenant provides a reusable screening report, the landlord must use it.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"Berkeley, CA","category":"application_screening_fees","lifecycle":"enacted","title":"Berkeley tenant screening fee rights disclosure (BMC 13.78.010)","requirement":"An owner or agent who charges an applicant a fee to obtain a consumer credit report and process a rental application must provide, in the application or in a separate disclosure before taking the fee, a clear and conspicuous tenant screening fee rights statement and the maximum fee cap under California Civil Code Section 1950.6(b).","key_value":null,"coverage_conditions":"Owners and their agents who charge screening fees for residential rental property in Berkeley.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Owners/agents charging screening fees on Berkeley rentals"},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Berkeley Mun. Code § 13.78.010","quoted_span":"the owner must provide, either in the rental application or in a separate disclosure before receiving the fee, a clear and conspicuous tenant screening fee rights statement and a statement of the maximum fee cap permitted under California Civil Code Section 1950.6(b).","interaction":"Local disclosure rule requires notice of the cap set by California Civil Code § 1950.6(b).","confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"Berkeley, CA","category":"application_screening_fees","lifecycle":"enacted","title":"Berkeley ban on non-refundable application fees for existing tenancies (BMC 13.78.016)","requirement":"An owner of residential rental property, or the owner’s agent, cannot charge an existing tenant a non-refundable fee to renew a tenancy, including any fee tied to a roommate departing or to a request to add or replace a roommate in a pre-existing household.","key_value":null,"coverage_conditions":"All residential rental agreements in Berkeley, regardless of lease language; any contrary lease provision is unenforceable.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Existing tenants in Berkeley residential rentals"},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Berkeley Mun. Code § 13.78.016","quoted_span":"An owner of residential rental property (or the owner’s agent) cannot charge a non-refundable fee to any existing tenant for the purpose of renewing a tenancy, in whole or in part, including any fee associated with the departure of a roommate or to request to add or replace a roommate in a pre-existing household.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
